def to_array(self):
        """
        Serializes this InlineQueryResultCachedVoice to a dictionary.

        :return: dictionary representation of this object.
        :rtype: dict
        """
        result = {
            'type': 'inline_query_result_cached_voice',
            'id': self.id,
            'voice_file_id': self.voice_file_id,
            'title': self.title
        }

        if self.caption:
            result['caption'] = self.caption

        if self.reply_markup:
            result['reply_markup'] = self.reply_markup.to_dict()

        if self.input_message_content:
            result['input_message_content'] = self.input_message_content.to_dict()

        if self.parse_mode:
            result['parse_mode'] = self.parse_mode

        return result

